-- Dis has three source layouts whose geometry is generated by Lua hooks.
-- Run them through the production catalog so their DES metadata, hooks,
-- stair completion, and floor cleanup are checked as one contract.
local branches = require("ids.branches")
local catalog = require("policy.generation.layouts.catalog")
local effects = require("constants.vault_effects")
local depth = require("policy.generation.vaults.depth")
local harness = require("tests.harness")
local weight = require("policy.generation.vaults.weight")

local test = {}

local layouts = {
    layout_subdivisions = 15,
    layout_jigsaw = 10,
    layout_overlapping_boxes = 5,
}

-- Use the same layout random stream as the live grid, with reproducible
-- draws that exercise different partition and room arrangements.
local function context_for(seed)
    local state = seed
    local context = {}

    -- Match the kernel's high/low draw shape on the layout stream.
    function context:random_u64(stream)
        harness.equal(stream, "layout", "Dis layout random stream")
        state = (state * 1664525 + 1013904223) % 4294967296

        return state, (state * 22695477 + 1) % 4294967296
    end

    return context
end

-- Every generated map must retain its source ID and enough traversable
-- ground to serve as a level after the shared stair pass.
local function check_layout(id, expected_weight)
    local definition = catalog.get(id)
    local decorated = 0

    harness.equal(weight.for_branch(definition, branches.BRANCH_DIS),
        expected_weight, id .. " source Dis weight")
    harness.falsy(depth.eligible(definition,
        branches.BRANCH_DUNGEON, 1, 15),
        id .. " is not a Dungeon candidate")

    for seed = 1, 6 do
        local result = catalog.execute(context_for(seed * 71), definition,
            branches.BRANCH_DIS, seed)
        local floor = 0
        local statues = 0
        local colours = 0
        local tiles = 0

        harness.equal(result.id, id, "executed Dis layout ID")
        harness.equal(#result.rows, 70, "Dis layout height")
        harness.equal(#result.rows[1], 80, "Dis layout width")
        harness.truthy(#result.stairs >= 3,
            "Dis layout has connected ordinary stairs")

        for _, row in ipairs(result.rows) do
            for glyph in row:gmatch(".") do
                if glyph == "." or glyph == "+" then
                    floor = floor + 1
                elseif glyph == "G" then
                    statues = statues + 1
                end
            end
        end

        for _, record in ipairs(result.records or {}) do
            if record.kind == effects.COLOUR then
                colours = colours + 1
            elseif record.kind == effects.TILE then
                tiles = tiles + 1
            end
        end

        harness.truthy(floor > 840,
            id .. " keeps the source divisions floor threshold")

        if id == "layout_subdivisions" then
            harness.equal(colours, statues,
                "each Dis statue retains its cyan source colour")
            harness.equal(tiles, statues,
                "each Dis statue retains its iron golem tile")
            decorated = decorated + statues
        end
    end

    if id == "layout_subdivisions" then
        harness.truthy(decorated > 0,
            "seed range exercises Dis statue decoration")
    end
end

-- Execute the whole source family rather than testing one procedural hook
-- in isolation; unrelated mod file order must not change the family set.
function test.run()
    catalog.load()

    for id, expected_weight in pairs(layouts) do
        check_layout(id, expected_weight)
    end
end

return test
